SELECT m.TRADEDATE AS `交易日期`, m.STOCKSNAME AS `股票名称`, m.SECCODE AS `股票代码`, ROUND(m.TCLOSE, 2) AS `收盘价(元)`, ROUND(m.TOPEN, 2) AS `开盘价(元)`, ROUND(m.THIGH, 2) AS `最高价(元)`, ROUND(m.TLOW, 2) AS `最低价(元)`, ROUND(m.TVALUE / 100000000, 2) AS `成交额(亿元)`, ROUND(m.TVOLUME / 1000000, 2) AS `成交量(百万股)`, ROUND(m.CHNG_PCT, 2) AS `涨跌幅(%)` FROM STK_MKT m WHERE m.ISVALID = 1 AND (m.STOCKSNAME LIKE '%宁德时代%' OR m.STOCKSNAME LIKE '%招商银行%') AND m.TRADEDATE = '2026-08-31' AND m.TCLOSE IS NOT NULL ORDER BY m.TCLOSE DESC;
